     byte *agree2 = (byte *)XMALLOC(DH_TEST_BUF_SIZE, HEAP_HINT, DYNAMIC_TYPE_TMP_BUFFER);

     if ((tmp == NULL) || (priv == NULL) || (pub == NULL) ||
